import unittest
from src.graph_tools import topological_sort

class GraphToolsTest(unittest.TestCase):
    def test_deterministic_topological_sort(self):
        result = topological_sort(['build', 'test', 'lint', 'deploy'], [('build', 'test'), ('build', 'lint'), ('test', 'deploy'), ('lint', 'deploy')])
        self.assertEqual(result, ['build', 'lint', 'test', 'deploy'])

    def test_includes_nodes_from_edges(self):
        self.assertEqual(topological_sort([], [('a', 'c'), ('b', 'c')]), ['a', 'b', 'c'])

    def test_cycle_rejected(self):
        with self.assertRaises(ValueError):
            topological_sort(['a', 'b'], [('a', 'b'), ('b', 'a')])

