def group_by_key(rows, key):
    """
    Groups an iterable of dictionaries by the value of a given key.
    Rows missing the key are grouped under None.
    Preserves original row order within each group.
    """
    result = {}
    for row in rows:
        val = row.get(key)
        if val not in result:
            result[val] = []
        result[val].append(row)
    return result

