def chunked(iterable, size):
    if size <= 0:
        raise ValueError("Size must be greater than 0")

    result = []
    current_chunk = []
    for item in iterable:
        current_chunk.append(item)
        if len(current_chunk) == size:
            result.append(tuple(current_chunk))
            current_chunk = []

    if current_chunk:
        result.append(tuple(current_chunk))

    return result

